from pathlib import Path
out=Path(__file__).parent
old=Path('validation/lung-next-v08423/atezo/source-cases.cjs').read_text()
immune=old[old.index("for(const [field,attr,lo"):old.index("for(let grade=0;grade<=4;grade++)for(let culprit")]
restart=old[old.index("test('restart incomplete'"):old.index("test('oral prescription not verified'")]
head="""'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert/strict');
const root=path.resolve(__dirname,'../../..'),E=require(path.join(root,'js/assessment-engine')),V=require(path.join(root,'js/protocol-validator')),D=require(path.join(root,'js/protocol-dose-schedule'));
const integrated=process.argv.includes('--integrated'),out=[],author=JSON.parse(fs.readFileSync(path.join(__dirname,'authoring.json'))).regimens;
for(const [code,file,folder,days,dose] of [['00544','00544-atezolizumab-1200-mg-monotherapy-21-day.json','lung',21,1200],['00592','00592-atezolizumab-840-mg-monotherapy-14-day.json','shared',14,840],['00593','00593-atezolizumab-maintenance.json','lung',28,1680]]){
const P=JSON.parse(fs.readFileSync(path.join(integrated?path.join(root,'protocols',folder):path.join(__dirname,'proposed'),file))),A=author[code];
function check(name,fn){try{fn();out.push({name:code+' '+name,pass:true});}catch(e){out.push({name:code+' '+name,pass:false,error:e.message});}}
function test(name,input,yes=[],no=[]){check(name,()=>{let r=E.assess(P,input);assert.deepEqual(r.errors,[]);assert.deepEqual(r.invalid,[]);let ids=r.findings.map(f=>f.ruleId);for(let id of yes)assert(ids.includes(id),'missing '+id+' got '+ids);for(let id of no)assert(!ids.includes(id),'unexpected '+id);});}
check('strict validator',()=>{let r=V.validate(P,{strict:true});assert.deepEqual(r.errors,[]);assert.deepEqual(r.warnings,[]);});
check('blank not proceed',()=>{let r=E.assess(P,{});assert.equal(r.findings.length,0);assert.notEqual(r.actionType,'proceed');});
check('optional and legacy inputs',()=>{let b=JSON.parse(fs.readFileSync(path.join(__dirname,'research','baseline-'+code+'.json')));for(let k of Object.keys(b.input_definitions))assert(P.input_definitions[k]);for(let d of Object.values(P.input_definitions)){assert.equal(d.required,false);assert.equal(d.demo_value,null);}});
check('governance and provenance',()=>{for(let obj of [P.metadata.validation,P.metadata.encoding_maturity])for(let k of ['clinical_use_authorised','consultant_reviewed','oncology_pharmacy_reviewed'])assert.equal(obj[k],false);assert.equal(P.metadata.source_checked_date,'2026-10-29');assert.match(P.metadata.source_pdf_sha256,/^[a-f0-9]{64}$/);assert.notEqual(P.metadata.source_pdf_sha256,P.metadata.source_text_snapshot_sha256);});
for(let g=0;g<=4;g++)test('ECOG '+g,{ecog:g},g>1?['ECOG_ELIGIBILITY']:[],g<2?['ECOG_ELIGIBILITY']:[]);
for(let [f,id,pos] of [['adult_patient','ADULT_ELIGIBILITY',false],['hypersensitivity','ICI_EXCLUSION_HYPERSENSITIVITY',true],['active_infection_requiring_therapy','ICI_ACTIVE_INFECTION_REQUIRING_THERAPY',true],['symptomatic_ild','SYMPTOMATIC_ILD',true],['symptomatic_cns_metastases','SYMPTOMATIC_CNS',true],['medical_condition_requires_immunosuppression','IMMUNOSUPPRESSION_EXCLUSION',true],['clinically_significant_autoimmune_disease','AUTOIMMUNE_CAUTION',true],['prior_pd1_pdl1_treatment','PRIOR_PD1_PDL1_REVIEW',true],['pregnancy','ICI_PREGNANCY_OR_BREASTFEEDING_REVIEW',true],['breastfeeding','ICI_PREGNANCY_OR_BREASTFEEDING_REVIEW',true],['myocarditis_suspected','SUSPECTED_MYOCARDITIS',true],['hlh_suspected','ICI_SUSPECTED_HLH',true],['recurrent_pancreatitis','ICI_PANCREATITIS_G4',true],['facial_paresis_not_fully_resolved','ICI_FACIAL_PARESIS_PERSISTENT',true],['fbc_clinical_concern','ICI_FBC_ABNORMALITY_REVIEW',true],['atezolizumab_dose_reduction_planned','ATEZO_DOSE_REDUCTION',true],['missed_atezolizumab_dose','MISSED_ATEZO_DOSE',true]]){test(f+' positive',{[f]:pos},[id]);test(f+' negative',{[f]:!pos},[],[id]);test(f+' missing',{},[],[id]);}
for(let g=0;g<=4;g++){let id=g>=3?'ICI_INFUSION_REACTION_G3_G4':'ICI_INFUSION_REACTION_G1_G2';test('infusion '+g,{infusion_reaction_grade:g},g?[id]:[],g?[]:['ICI_INFUSION_REACTION_G3_G4','ICI_INFUSION_REACTION_G1_G2']);}
for(let v of [29.99,30,30.01])test('stable renal '+v,{crcl_ml_min_exact:v},v<30?['RENAL_LIMITED_DATA']:v===30&&code!=='00544'?['RENAL_30_SOURCE_GAP']:[],v>=30?['RENAL_LIMITED_DATA']:[]);
test('dialysis',{haemodialysis:true},['RENAL_LIMITED_DATA']);test('severe hepatic',{hepatic_impairment:'severe'},['HEPATIC_SEVERE_LIMITED_DATA']);test('mild hepatic',{hepatic_impairment:'mild'},[],['HEPATIC_SEVERE_LIMITED_DATA']);
const criteria={a:'post_chemo_source_criteria_met',b:'uc_post_platinum_criteria_met',c:'uc_cisplatin_ineligible_pdl1_criteria_met',d:'first_line_source_criteria_met',[code==='00593'?'f':'e']:'adjuvant_source_criteria_met',[code==='00593'?'e':'f']:'sclc_induction_completed'};
for(let [letter,f] of Object.entries(criteria)){test('indication missing '+letter,{indication_id:code+letter},['INDICATION_'+letter.toUpperCase()+'_UNASSESSED']);test('indication fails '+letter,{indication_id:code+letter,[f]:false},['INDICATION_'+letter.toUpperCase()+'_NOT_MET']);test('indication confirmed '+letter,{indication_id:code+letter,[f]:true},[],['INDICATION_'+letter.toUpperCase()+'_NOT_MET','INDICATION_'+letter.toUpperCase()+'_UNASSESSED']);}
"""
tail="""
check('dose schedule real renderer',()=>{let m=D.buildModel(P);assert.equal(m.phases.length,1);assert.equal(P.treatment_phases[0].cycle_length_days,days);assert.deepEqual(P.treatment_phases[0].active_drugs,['atezolizumab']);assert(m.phases[0].components.some(c=>c.id==='atezolizumab'&&c.dose.includes(String(dose))));assert.equal(!!P.treatment_phases[0].administration[0].dose.options,code==='00544');});
check('specific named dose hold survives combined endocrine exception',()=>{let r=E.assess(P,{pneumonitis_grade:2,other_immune_toxicity_grade:4,other_event_is_controlled_endocrinopathy:true});assert(r.findings.find(f=>f.ruleId==='ICI_PNEUMONITIS_G2').action.components.includes('atezolizumab'));let m=D.buildModel(P,{assessment:r});assert(m.phases.length);});
check('full suite source graph',()=>{const ids=new Set(A.patient.sources.map(s=>s.id));function walk(o){if(!o||typeof o!=='object')return;for(let[k,v]of Object.entries(o)){if(['source_ids','urgent_source_ids','support_source_ids'].includes(k))for(let id of v)assert(ids.has(id),id);else walk(v);}}walk(A);assert.deepEqual(A.patient.evidence.metrics,[]);assert(A.patient.chapters.length>=4);assert(A.patient.anatomy.every(x=>x.length===6));assert(A.clinical.patient_selection.eligibility_orientation.length);assert(A.journey.lanes.every(l=>l.cells.length===A.journey.stages.length));assert.equal(A.support_plans[0].medicines.length,0);assert.equal(A.card_contexts.filter(x=>x.intent==='adjuvant').length,1);assert(!JSON.stringify(A).match(/KEYNOTE|keynote|24-month|pembrolizumab/i));});
check('source edition and impairment boundary',()=>{for(let[k,d]of Object.entries(P.input_definitions))if(k.endsWith('_grade')){assert(!d.ctcae_version);assert(d.grading_source_label.includes(code==='00544'?'unspecified':'4.0'));}assert.equal(P.input_definitions.crcl_ml_min_exact.renal_input.exact_value_required,false);});
}
const result={mode:integrated?'integrated':'proposed',total:out.length,passed:out.filter(x=>x.pass).length,failed:out.filter(x=>!x.pass).length,clinical_use_authorised:false,results:out};fs.writeFileSync(path.join(__dirname,result.mode+'-results.json'),JSON.stringify(result,null,2)+'\\n');console.log(JSON.stringify({...result,results:undefined,failures:out.filter(x=>!x.pass)},null,2));if(result.failed)process.exitCode=1;
"""
(out/'source-cases.cjs').write_text(head+immune+restart+tail)
